package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaPlDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Ochrona przed wszelkim złem", "W imię Allaha, w imię którego nic na ziemi ani w niebiosach nie może wyrządzić szkody. On jest Wszechsłyszący, Wszechwiedzący.", "Trzy razy każdego ranka i wieczoru.", "Ktokolwiek powie to trzy razy rano i wieczorem, nic mu nie zaszkodzi."),
        "dua_raditu_billahi" to DuaText("Zadowolenie z Allaha jako Pana", "Jestem zadowolony z Allaha jako mojego Pana, islamu jako mojej religii i Mahometa ﷺ jako mojego Proroka.", "Trzy razy rano i wieczorem.", "Allah ma prawo zadowolić go w Dniu Sądu."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah wystarczy)", "Wystarczy mi Allah; nie ma boga poza Nim. W Nim pokładam swą ufność i On jest Panem Potężnego Tronu.", "Siedem razy rano i wieczorem.", "Werset Koranu; Allah wystarczy na troski tego świata i życia ostatecznego."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubhanAllahi wa bihamdihi", "Chwała Allahowi i wszelka chwała należy do Niego.", "Sto razy dziennie.", "Ktokolwiek będzie to powtarzał sto razy dziennie, zostaną mu odpuszczone grzechy, choćby były jak piana morska."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza. Do Niego należy panowanie i do Niego należy chwała. On jest nad każdą rzeczą wszechwładny.", "Wielka cnota, gdy mówię to sto razy dziennie.", "Nagrodą jest uwolnienie dziesięciu niewolników, napisanie stu dobrych uczynków, wymazanie stu grzechów i ochrona przed Szaytanem aż do wieczora."),
        "dua_leaving_mosque" to DuaText("Opuszczenie meczetu", "O Allahu, proszę Cię o Twoją łaskę.", "Przy wyjściu z meczetu lewą nogą.", "Prośba o łaskę i zaopatrzenie Allaha przy opuszczaniu meczetu."),
        "dua_after_adhan" to DuaText("Po Adhanie", "O Allahu, Panie tego doskonałego wezwania i modlitwy, która ma się wkrótce rozpocząć, obdarz Muhammada ﷺ al-Wasilah i cnotą i wynieś go do chwalebnej stacji, którą mu obiecałeś.", "Po zakończeniu adhanu.", "Ktokolwiek to powie, otrzyma wstawiennictwo Proroka ﷺ w Dniu Sądu."),
        "dua_after_salah_istighfar" to DuaText("Po Fardzie Salahu", "Proszę o przebaczenie Allaha (3 razy). O Allahu, jesteś as-Salam i od Ciebie pochodzi pokój. Błogosławiony jesteś, Władco Majestatu i Honoru.", "Zaraz po salamie.", "Prorok ﷺ recytował to po każdej obowiązkowej modlitwie."),
        "dua_after_salah_help_dhikr" to DuaText("Pomóż mi Cię zapamiętać", "O Allahu, pomóż mi pamiętać o Tobie, dziękować Ci i oddawać Ci cześć w najlepszy sposób.", "Po każdej modlitwie – Prorok ﷺ radził Mu'adhowi (RA), aby ją odmawiał.", "Specjalna rada Proroka ﷺ – doskonałość i stałość w oddawaniu czci."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Fatimi przed snem", "Chwała Allahowi (33), wszelka chwała Allahowi (33), Allah jest Największy (34).", "Przed snem — Prorok ﷺ nauczył tego Fatimę i Alego (RA).", "Prorok ﷺ powiedział, że jest to lepsze dla ciebie niż sługa."),
        "dua_sleep_qina_adhab" to DuaText("Ochrona przed karą", "Allahu, chroń mnie przed Twoją karą w Dniu, w którym wskrzesisz swoje sługi.", "Trzy razy, prawą ręką umieszczoną pod policzkiem.", "Zamienia sen w przypomnienie śmierci i przygotowanie na życie ostateczne."),
        "dua_bad_dream" to DuaText("Po złym śnie", "Szukam schronienia u Allaha przed Szaytanem, przeklętym.", "Po złym śnie: wypluj suchą ślinę lekko trzy razy w lewo, a następnie skręć na drugą stronę.", "Zły sen nie zaszkodzi ci; nie mów o tym nikomu."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "O Wiecznie Żyjący, O Podtrzymujący wszystkich! Przez Twoje miłosierdzie szukam pomocy.", "Kiedy sprawa staje się bardzo ciężka.", "Ilekroć coś niepokoiło Proroka ﷺ, mówił to."),
        "dua_entering_market" to DuaText("Wejście na Rynek", "Nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza. Do Niego należy panowanie i Jego chwała. On daje życie i powoduje śmierć. On jest wiecznie żywy i nigdy nie umiera. W Jego rękach jest wszystko dobro i On ma władzę nad każdą rzeczą.", "Przy wejściu na rynek.", "Hadis wspomina o wielkiej nagrodzie za to (milion dobrych uczynków)."),
        "dua_adam_forgiveness" to DuaText("Dua proroka Adama (AS)", "Panie nasz, sami siebie skrzywdziliśmy i jeśli nam nie przebaczysz i nie zmiłujesz się nad nami, z pewnością znajdziemy się wśród stratnych.", "Duet pokuty Adama i Hawwy (AS).", "Pierwsza pokuta ludzkości – Allah ją przyjął."),
        "dua_abu_bakr" to DuaText("Dua nauczał Abu Bakra (RA)", "O Allahu, wyrządziłem sobie wielką krzywdę i nikt nie przebacza grzechów oprócz Ciebie, więc udziel mi przebaczenia od Ciebie i zmiłuj się nade mną. Zaprawdę, Ty jesteś Przebaczający, Litościwy.", "Prorok ﷺ nauczył Abu Bakra as-Siddiqa (RA) odmawiania w modlitwie (po tashahhud).", "Sunna dua na zakończenie modlitwy."),
        "dua_astaghfirullah_atubu" to DuaText("Codziennie Istighfar", "Szukam przebaczenia Allaha i zwracam się do Niego w pokucie.", "Prorok ﷺ szukał przebaczenia ponad siedemdziesiąt razy dziennie.", "Prorok ﷺ powiedział: Szukam przebaczenia Allaha i pokutuję przed Nim ponad siedemdziesiąt razy dziennie."),
        "dua_laylatul_qadr" to DuaText("Dua w imieniu Laylat al-Qadr", "O Allahu, jesteś najbardziej przebaczający i kochasz przebaczać, więc przebacz mi.", "Nauczony Aishy (RA) dla Laylat al-Qadr.", "Specjalny duet na ostatnie noce Ramadanu i Laylat al-Qadr."),
        "dua_family_coolness" to DuaText("Chłód oczu (małżonek i dzieci)", "Panie nasz, udziel nam od naszych małżonków i potomstwa chłodu naszych oczu i uczyń nas przywódcami sprawiedliwych.", "Koraniczny duet dla prawego małżonka i dzieci.", "O pokój w domu i prawe dzieci."),
        "dua_righteous_children" to DuaText("Dla Sprawiedliwych Potomków", "Panie mój, daj mi od siebie czyste potomstwo. Zaprawdę, Ty jesteś słuchaczem błagań.", "Dua Proroka Zakariyya (AS).", "Koraniczny duet dla poszukujących dzieci."),
        "dua_ibrahim_prayer_family" to DuaText("Założyciele modlitwy", "Panie mój, uczyń mnie założycielem modlitwy i mojego potomstwa. Panie nasz, przyjmij moje błaganie. Panie nasz, przebacz mi, moim rodzicom i wierzącym w Dniu założenia rachunku.", "Dua Proroka Ibrahima (AS) dla niego i jego potomków.", "Często odmawiane na końcu modlitwy."),
        "dua_newlywed" to DuaText("Gratulacje dla Nowożeńców", "Niech Allah was błogosławi, ześle na was błogosławieństwo i złączy was oboje w dobroci.", "Kiedy gratulujemy komuś związku małżeńskiego.", "Gratulacje Sunny z okazji małżeństwa."),
        "dua_before_eating" to DuaText("Przed jedzeniem", "W imię Allaha. (Jeśli zapomniano:) W imię Allaha, na początku i na końcu.", "Przed jedzeniem. Jeśli zapomnisz, powiedz to w połowie.", "Powiedzenie Bismillah powstrzymuje Szaytana od dzielenia się jedzeniem."),
        "dua_after_eating" to DuaText("Po jedzeniu", "Wszelka chwała należy się Allahowi, który mnie tym nakarmił i zapewnił mi to bez żadnej mocy ani mocy z mojej strony.", "Po skończonym posiłku.", "Przeszłe grzechy tego, który to mówi, są odpuszczone."),
        "dua_host" to DuaText("Dla Gospodarza", "O Allahu, pobłogosław ich w tym, czym ich obdarzyłeś, przebacz im i zmiłuj się nad nimi.", "Dla gospodarza, po jedzeniu u kogoś w domu.", "Dziękowanie gospodarzowi w sposób Sunny."),
        "dua_breaking_fast" to DuaText("Po przerwaniu postu", "Pragnienie ustąpiło, żyły nawilżyły się i nagroda została przyznana, jeśli Allah pozwoli.", "W czasie iftaru.", "Prorok ﷺ powiedział to, przerywając post."),
        "dua_new_clothes" to DuaText("Noszenie nowych ubrań", "O Allahu, wszelka chwała jest Twoja; Ubrałeś mnie w to. Proszę Cię o jego dobro i dobro tego, do czego zostało stworzone, i szukam u Ciebie schronienia przed jego złem i złem tego, do czego zostało stworzone.", "Podczas noszenia nowego ubrania (nadawania mu nazwy, np. koszuli lub turbanu).", "Prorok ﷺ wykonał ten dua, mając na sobie nową szatę. (Codzienny zestaw ubrań znajduje się w sekcji „Ubieranie się”)."),
        "dua_rabbana_atina" to DuaText("Dobro na tym świecie i w życiu ostatecznym", "Panie nasz, obdarz nas dobrem na tym świecie i dobrem w życiu ostatecznym i chroń nas od kary ognia.", "Najczęściej tworzony dua Proroka ﷺ.", "Dua, która gromadzi wszelkie dobro tego świata i zaświatów."),
        "dua_rabbi_zidni_ilma" to DuaText("Wzrost wiedzy", "Panie mój, pomnóż moją wiedzę.", "Dla poszerzenia wiedzy.", "Allah nakazał Prorokowi ﷺ prosić o wzrost jedynie wiedzy."),
        "dua_musa_sharh_sadr" to DuaText("Otwarcie skrzyni (Musa AS)", "Panie mój, rozszerz moją klatkę piersiową, ułatwij mi zadanie i rozwiąż węzeł z mojego języka, aby mogli zrozumieć moją mowę.", "Przed egzaminem, przemówieniem lub jakimkolwiek trudnym zadaniem.", "Dua Proroka Musy (AS) — spokój serca i łatwość w pracy."),
        "dua_la_tuzigh" to DuaText("Niezłomność Serca", "Panie nasz, nie pozwól, aby nasze serca zachwiały się po tym, jak nas prowadziłeś, i obdarz nas miłosierdziem od siebie. Zaprawdę, Ty jesteś Dawcą.", "O wytrwałość w kierowaniu.", "Duet za wytrwanie w wierze."),
        "dua_ya_muqallib" to DuaText("O Przemieniaczu Serc", "O Przemieniaczu serc, trzymaj moje serce mocno przy Twojej religii.", "Prorok ﷺ często tworzył ten duet.", "Według Umm Salamah (RA), dua Proroka ﷺ była najczęściej tworzona."),
        "dua_la_tuakhidhna" to DuaText("Ostatnie wersety Sury Al-Baqarah", "Panie nasz, nie karz nas za to, jeśli zapomnimy lub popełnimy błąd. Panie nasz, nie nakładaj na nas takiego ciężaru, jaki nałożyłeś na tych, którzy byli przed nami. Panie nasz, nie obciążaj nas tym, czego nie jesteśmy w stanie unieść. Przebacz nam, przebacz nam i zmiłuj się nad nami. Jesteś naszym Obrońcą, więc pomóż nam w walce z niewiernymi.", "W nocy przed snem — dwa ostatnie wersety Sury al-Baqarah.", "Ktokolwiek w nocy recytuje dwa ostatnie wersety Sury al-Baqarah, to mu wystarczy."),
        "dua_visiting_sick" to DuaText("Odwiedziny Chorych", "Proszę Allaha Potężnego, Pana Potężnego Tronu, aby cię uzdrowił.", "Siedem razy podczas odwiedzania chorych.", "Jeśli czas śmierci nie nadejdzie, Allah go uzdrowi."),
        "dua_ruqyah_pain" to DuaText("Na ból ciała", "Szukam schronienia u Allaha i Jego mocy przed złem tego, co czuję i czego się boję.", "Połóż rękę tam, gdzie boli, powiedz trzy razy „Bismillah”, a następnie siedem razy „dua”.", "Prorok ﷺ nauczył tego Uthmana ibn Abila – As (RA) na ból."),
        "dua_ruqyah_nabawi" to DuaText("Prorocza Ruqyah dla chorych", "O Allahu, Panie ludzkości! Usuń krzywdę i udziel lekarstwa, bo Ty jesteś Tym, który leczy; nie ma innego lekarstwa poza Twoim lekarstwem – lekarstwem, które nie pozostawia żadnej choroby.", "Przekazując rękę nad chorym.", "Prorok ﷺ recytował to, odwiedzając chorych członków swojej rodziny."),
        "dua_kalimat_tammat" to DuaText("Szukanie schronienia w doskonałych słowach", "Szukam schronienia w doskonałych słowach Allaha przed złem tego, co stworzył.", "Podczas zatrzymania się w danym miejscu lub wieczorem.", "Ktokolwiek zatrzyma się w jakimś miejscu i to powie, nic mu nie zaszkodzi, dopóki z niego nie opuści."),
        "dua_evil_eye" to DuaText("Ochrona dzieci (złe oko)", "Szukam dla was ochrony w doskonałych słowach Allaha przed każdym diabłem i wszelkim jadowitym stworzeniem, i przed każdym szkodliwym okiem.", "Prorok ﷺ wyrecytował to nad Hasanem i Husainem (RA).", "Sunna dua chroniąca dzieci przed złym okiem i krzywdą (w przypadku jednego dziecka powiedz „U'īdhuka”)."),
        "dua_seeing_afflicted" to DuaText("Widzenie kogoś na rozprawie", "Wszelka chwała należy się Allahowi, który oszczędził mi tego, czym was doświadczył i obdarzył mnie większą łaską niż większość swego stworzenia.", "Widząc kogoś na rozprawie (powiedz to sobie cicho).", "Ten, kto tak mówi, jest chroniony przed tą próbą."),
        "dua_istikhara" to DuaText("Salat al-Istikhara", "O Allahu, szukam dobra dzięki Twojej wiedzy, szukam możliwości dzięki Twojej mocy i proszę Cię o Twoją wielką łaskę. Ty masz moc, a ja nie mam żadnej; Ty wiesz, a ja nie, i Ty jesteś Znawcą tego, co skryte. O Allahu, jeśli według Twojej wiedzy ta sprawa (przypomnij sobie) jest dobra dla mojej religii, mojego życia i mojego końca, to zarządz to dla mnie, ułatwij mi to i pobłogosław mnie w tym. A jeśli według Twojej wiedzy ta sprawa jest zła dla mojej religii, mojego życia i mojego końca, to odwróć ją ode mnie i odwróć mnie od niej, i zarządź dla mnie dobro, gdziekolwiek by to było, i spraw, żebym się tym zadowolił.", "Po dwóch rak'ach dobrowolnej modlitwy, aby szukać tego, co najlepsze w dopuszczalnej sprawie.", "Prorok ﷺ nauczał Towarzyszy istikhara we wszystkich sprawach, tak jak uczył ich sury Koranu."),
    )
}
